package br.com.luvi.financaspessoais.usuario.service;
import br.com.luvi.financaspessoais.usuario.entity.Usuario; import br.com.luvi.financaspessoais.usuario.repository.UsuarioRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class UsuarioService { private final UsuarioRepository repo; private final PasswordEncoder encoder; public UsuarioService(UsuarioRepository r,PasswordEncoder e){repo=r;encoder=e;} @Transactional public Usuario cadastrar(String nome,String email,String senha){String e=email.trim().toLowerCase(); if(repo.existsByEmailIgnoreCase(e))throw new IllegalArgumentException("Este e-mail já está cadastrado."); if(senha==null||senha.length()<6)throw new IllegalArgumentException("A senha deve ter pelo menos 6 caracteres."); Usuario u=new Usuario();u.setNome(nome.trim());u.setEmail(e);u.setLogin(e);u.setSenha(encoder.encode(senha));return repo.save(u);} public Usuario atual(String login){return repo.findByLoginIgnoreCase(login).orElseGet(()->repo.findByEmailIgnoreCase(login).orElseThrow());} }